from dataclasses import dataclass

@dataclass(frozen=True)
class AgentContext:
    agent_name: str = "Status Desk"
    conversation_id: str = "conv_status_approved_46c2"

TOOL_DEFINITIONS = {
    "read_health": {"type": "function", "description": "Read synthetic service health."},
    "read_queue": {"type": "function", "description": "Read synthetic pending queue depth."},
}

async def read_health(service):
    return {"service": service, "status": "healthy"}

async def read_queue(service):
    return {"service": service, "depth": 2}

HANDLERS = {"read_health": read_health, "read_queue": read_queue}

async def execute_tool(context, tool_name, arguments):
    definition = TOOL_DEFINITIONS[tool_name]
    return await HANDLERS[tool_name](**arguments)

async def status_turn(context, question):
    health = await execute_tool(context, "read_health", {"service": "checkout"})
    queue = await execute_tool(context, "read_queue", {"service": "checkout"})
    return {"health": health, "queue": queue}

# Source-only caller binding, approved opaque span correlation, not metric labels.
context = AgentContext()
